mapper.select:
SELECT o.*, (SELECT SUM(p.prdPrice * op.ordQty) FROM order_product op, product p WHERE op.prdNo=p.prdNo AND op.ordNo=o.ordNo) AS totalPrice, (SELECT LISTAGG(p.prdName || ' ' || op.ordQty || '개', ', ') WITHIN GROUP (ORDER BY p.prdName) FROM order_product op, product p WHERE op.prdNo=p.prdNo AND op.ordNo=o.ordNo) AS orderItems FROM order_info o
o.memId=#{memId}
ORDER BY o.ordDate DESC
